    /** What is due on the claim at its person's rate in force on the claim's date: amount times pct,
     * divided by 100, rounded to two decimals as the claim rounds (see {@link #roundingOf}) — the rate
     * figure alone, before any late charge or floor (see {@link #liveDueOf}); null when no
     * rate of the grade in force for them on the claim's date applies then. */
    public BigDecimal dueOf(Claim claim, Person person) {
        return dueOf(claim, person, live(claim.getSheetId()));
    }

    private BigDecimal dueOf(Claim claim, Person person, Basis basis) {
        RoundingMode rounding = roundingOf(claim, basis);
        return basis.rateFor(claim, person.gradeOn(claim.getDate()), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
                .orElse(null);
    }

    /** How the claim's live figures round: by the rounding mode in force on its date when there is one;
     * else half up when it is dated before the sheet's policy date in force, half to even when on or
     * after it. A correction rounds by the date of the claim it corrects. */
    private static RoundingMode roundingOf(Claim claim, Basis basis) {
        LocalDate dated = claim.getDate();
        if (claim.isCorrection() && claim.getCorrects() != null) {
            dated = basis.claimNumbered(claim.getPersonId(), claim.getCorrects()).map(Claim::getDate).orElse(dated);
        }
        RoundingMode mode = basis.roundingOn(dated);
        if (mode != null) return mode;
        LocalDate policyDate = basis.policyDateInForce();
        if (policyDate == null) return RoundingMode.HALF_EVEN;
        return dated.isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    private static String text(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}
package net.officefloor.hq.app.settings;

/** A user's role on a sheet. Every name is a clerk unless made a steward or a viewer. */
public enum Role {
    /** May settle a claim only when its due is at or below the sheet's clerk limit. */
    CLERK,
    /** May settle any claim. */
    STEWARD,
    /** Sees every screen and figure and may change nothing. */
    VIEWER
}
package net.officefloor.hq.app.claim;

import java.util.Set;

/** Where a claim is in its life: added as a draft, opened, then settled. A clerk's settle of a claim
 * whose due is above the clerk limit leaves it PENDING until a steward approves it (SETTLED) or rejects
 * it (back to OPEN). A draft, open or pending claim can be voided, and a settled one by a steward
 * within 7 days of its settlement. A voided claim cannot change status. A draft can be DELETED, and a
 * deleted claim made a DRAFT again (restored) on the same sheet-today it was deleted. A claim opened while its
 * due is above the review threshold in force on its date goes to REVIEW instead of OPEN, counting nowhere,
 * until a steward reviews it (OPEN); a claim in REVIEW can also be voided. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether a claim in this status counts toward what its person has claimed and is due. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether a claim in this status is still open: OPEN, or PENDING, which is handled like OPEN
     * (it goes overdue, bears the late charge and leaves the totals when dated within a hold of its person). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status may move to {@code next}. */
    public boolean canBecome(ClaimStatus next) {
        return switch (this) {
            case DRAFT -> Set.of(OPEN, VOID, DELETED, REVIEW).contains(next);
            case REVIEW -> Set.of(OPEN, VOID).contains(next);
            case OPEN -> Set.of(PENDING, SETTLED, VOID).contains(next);
            case PENDING -> Set.of(OPEN, SETTLED, VOID).contains(next);
            case SETTLED -> next == VOID;
            case VOID -> false;
            case DELETED -> next == DRAFT;
        };
    }
}

